UPDATE t_stock
SET quantity = quantity - #{quantity},
version   = version + 1
WHERE branch_id   = #{branchId}
AND material_id = #{materialId}
AND quantity   >= #{quantity}

UPDATE t_stock
SET quantity = quantity + #{quantity},
version   = version + 1
WHERE branch_id   = #{branchId}
AND material_id = #{materialId}

UPDATE t_stock
SET quantity = #{quantity},
version   = version + 1
WHERE branch_id   = #{branchId}
AND material_id = #{materialId}
